    const PtrPendingCache = bun.HiveArray(ResolveInfoRequest(c_ares.struct_hostent, "ptr").PendingCacheKey, 32);
    const CnamePendingCache = bun.HiveArray(ResolveInfoRequest(c_ares.struct_hostent, "cname").PendingCacheKey, 32);
    const APendingCache = bun.HiveArray(ResolveInfoRequest(c_ares.hostent_with_ttls, "a").PendingCacheKey, 32);
    const AAAAPendingCache = bun.HiveArray(ResolveInfoRequest(c_ares.hostent_with_ttls, "aaaa").PendingCacheKey, 32);
    const AnyPendingCache = bun.HiveArray(ResolveInfoRequest(c_ares.struct_any_reply, "any").PendingCacheKey, 32);
    const AddrPendingCache = bun.HiveArray(GetHostByAddrInfoRequest.PendingCacheKey, 32);
    const NameInfoPendingCache = bun.HiveArray(GetNameInfoRequest.PendingCacheKey, 32);
    pub const CacheHit = union(enum) {
            inflight: *GetAddrInfoRequest.PendingCacheKey,
            new: *GetAddrInfoRequest.PendingCacheKey,
            disabled: void,
        };
    pub const ChannelResult = union(enum) {
            err: c_ares.Error,
            result: *c_ares.Channel,
        };
};

pub const GetAddrInfoAsyncCallback = *const fn (i32, ?*std.c.addrinfo, ?*anyopaque) callconv(.c) void;
pub const LibInfoGetaddrinfoAsyncStart = *const fn (*bun.mach_port, ?[*:0]u8, ?[*:0]u8, ?*const std.c.addrinfo, GetAddrInfoAsyncCallback, ?*anyopaque) callconv(.c) i32;
pub const LibInfoGetaddrinfoAsyncHandleReply = *const fn (?*bun.mach_port) callconv(.c) i32;
pub const LibInfoGetaddrinfoAsyncCancel = *const fn (?*bun.mach_port) callconv(.c) void;

pub fn normalizeDNSName(name: []const u8, backend: *GetAddrInfo.Backend) []const u8 {
        if ((backend.* == .c_ares)) {
            if (strings.endsWithComptime(name, ".localhost")) {
                backend.* = .system;
                return "localhost";
            } else {
                if (strings.endsWithComptime(name, ".local")) {
                    backend.* = .system;
                } else {
                    if (strings.isIPV6Address(name)) {
                        backend.* = .system;
                    } else {
                        if (strings.eqlComptime(name, "localhost")) {
                            backend.* = .system;
                        }
                    }
                }
            }
        }
        return name;
}

pub fn ResolveInfoRequest(comptime cares_type: type, comptime type_name: []const u8) type {
        return struct {
        const request_type = @This();
        const log = Output.scoped(.ResolveInfoRequest, .hidden);

        resolver_for_caching: ?*Resolver = null,
        hash: u64 = 0,
        cache: CacheConfig = .{},
        head: CAresLookup(cares_type, type_name),
        tail: *CAresLookup(cares_type, type_name) = undefined,

        pub fn init(
            cache: Resolver.LookupCacheHit(@This()),
            resolver: ?*Resolver,
            name: []const u8,
            globalThis: *jsc.JSGlobalObject,
            comptime cache_field: []const u8,
        ) !*@This() {
            var request = try globalThis.allocator().create(@This());
            var hasher = std.hash.Wyhash.init(0);
            hasher.update(name);
            const hash = hasher.final();
            var poll_ref = Async.KeepAlive.init();
            poll_ref.ref(globalThis.bunVM());
            if (resolver) |resolver_| resolver_.ref();
            request.* = .{
                .resolver_for_caching = resolver,
                .hash = hash,
                .head = .{
                    .resolver = resolver,
                    .poll_ref = poll_ref,
                    .globalThis = globalThis,
                    .promise = jsc.JSPromise.Strong.init(globalThis),
                    .allocated = false,
                    .name = name,
                },
            };
            request.tail = &request.head;
            if (cache == .new) {
                request.resolver_for_caching = resolver;
                request.cache = @This().CacheConfig{
                    .pending_cache = true,
                    .entry_cache = false,
                    .pos_in_pending = @as(u5, @truncate(@field(resolver.?, cache_field).indexOf(cache.new).?)),
                    .name_len = @as(u9, @truncate(name.len)),
                };
                cache.new.lookup = request;
            }
            return request;
        }

        pub const CacheConfig = packed struct(u16) {
            pending_cache: bool = false,
            entry_cache: bool = false,
            pos_in_pending: u5 = 0,
            name_len: u9 = 0,
        };

        pub const PendingCacheKey = struct {
            hash: u64,
            len: u16,
            lookup: *request_type = undefined,

            pub fn append(self: *PendingCacheKey, cares_lookup: *CAresLookup(cares_type, type_name)) void {
                const tail = self.lookup.tail;
                tail.next = cares_lookup;
                self.lookup.tail = cares_lookup;
            }

            pub fn init(name: []const u8) PendingCacheKey {
                var hasher = std.hash.Wyhash.init(0);
                hasher.update(name);
                const hash = hasher.final();
                return PendingCacheKey{
                    .hash = hash,
                    .len = @as(u16, @truncate(name.len)),
                    .lookup = undefined,
                };
            }
        };

        pub fn onCaresComplete(self: *@This(), err_: ?c_ares.Error, timeout: i32, result: ?*cares_type) void {
            if (self.resolver_for_caching) |resolver| {
                defer resolver.requestCompleted();
                if (self.cache.pending_cache) {
                    resolver.drainPendingCares(
                        self.cache.pos_in_pending,
                        err_,
                        timeout,
                        @This(),
                        cares_type,
                        type_name,
                        result,
                    );
                    return;
                }
            }

            var head = self.head;
            bun.default_allocator.destroy(self);
            head.processResolve(err_, timeout, result);
        }
    };
}

pub extern "c" fn getaddrinfo_send_reply(port: bun.mach_port, reply: LibInfo.GetaddrinfoAsyncHandleReply) callconv(.c) bool;

pub fn CAresLookup(comptime cares_type: type, comptime type_name: []const u8) type {
        return struct {
        const log = Output.scoped(.CAresLookup, .hidden);

        resolver: ?*Resolver,
        globalThis: *jsc.JSGlobalObject,
        promise: jsc.JSPromise.Strong,
        poll_ref: Async.KeepAlive,
        allocated: bool = false,
        next: ?*@This() = null,
        name: string,

        pub fn new(data: @This()) *@This() {
            bun.assert(data.allocated);
            return bun.new(@This(), data);
        }

        pub fn init(resolver: ?*Resolver, globalThis: *jsc.JSGlobalObject, _: std.mem.Allocator, name: string) !*@This() {
            if (resolver) |resolver_| {
                resolver_.ref();
            }

            var poll_ref = Async.KeepAlive.init();
            poll_ref.ref(globalThis.bunVM());
            return @This().new(
                .{
                    .resolver = resolver,
                    .globalThis = globalThis,
                    .promise = jsc.JSPromise.Strong.init(globalThis),
                    .poll_ref = poll_ref,
                    .allocated = true,
                    .name = name,
                },
            );
        }

        pub fn processResolve(self: *@This(), err_: ?c_ares.Error, _: i32, result: ?*cares_type) void {
            const syscall = std.fmt.comptimePrint("query{c}{s}", .{ std.ascii.toUpper(type_name[0]), type_name[1..] });
            defer if (result) |r| r.deinit();

            if (err_) |err| {
                err.toDeferred(syscall, self.name, &self.promise).rejectLater(self.globalThis);
                self.release();
                return;
            }
            if (result == null) {
                c_ares.Error.ENOTFOUND.toDeferred(syscall, self.name, &self.promise).rejectLater(self.globalThis);
                self.release();
                return;
            }

            const node = result.?;
            const array = node.toJSResponse(self.globalThis.allocator(), self.globalThis, type_name) catch .zero;
            self.onComplete(array);
        }

        pub fn onComplete(self: *@This(), result: jsc.JSValue) void {
            const promise = self.promise;
            const globalThis = self.globalThis;
            self.promise = .{};
            promise.resolveTask(globalThis, result) catch {};
            if (self.resolver) |resolver| {
                resolver.requestCompleted();
            }
            self.release();
        }

        pub fn release(self: *@This()) void {
            self.poll_ref.unref(self.globalThis.bunVM());
            bun.default_allocator.free(self.name);
            if (self.resolver) |resolver| {
                resolver.deref();
            }
            if (self.allocated) {
                bun.destroy(self);
            }
        }

        pub fn deinit(self: *@This()) void {
            self.release();
        }
    };
}

